BY_KEY = {r["key"]: r for r in REGISTER}
CLASSIFICATIONS = ("actual", "published", "estimated", "simulated")


def get(key: str) -> dict | None:
    return BY_KEY.get(key)


def numeric(key: str, default: float) -> float:
    r = BY_KEY.get(key)
    return float(r["numeric_value"]) if r and r.get("numeric_value") is not None else default
